svg.script:
// Interactive SVG logic for pan, zoom, and highlighting

(function() {
    let svg = document.querySelector('svg');
    if (!svg) return;

    // Pan and Zoom state
    let state = {
        panning: false,
        pointX: 0,
        pointY: 0,
        scale: 1,
        viewBox: { x: 0, y: 0, w: 0, h: 0 }
    };

    // Initialize viewBox
    const vb = svg.viewBox.baseVal;
    state.viewBox = { x: vb.x, y: vb.y, w: vb.width, h: vb.height };

    // Mouse events for Panning
    svg.addEventListener('mousedown', (e) => {
        state.panning = true;
        state.pointX = e.clientX;
        state.pointY = e.clientY;
        svg.style.cursor = 'grabbing';
    });

    window.addEventListener('mouseup', () => {
        state.panning = false;
        svg.style.cursor = 'grab';
    });

    window.addEventListener('mousemove', (e) => {
        if (!state.panning) return;
        e.preventDefault();

        const dx = (e.clientX - state.pointX) / state.scale;
        const dy = (e.clientY - state.pointY) / state.scale;

        state.viewBox.x -= dx;
        state.viewBox.y -= dy;

        state.pointX = e.clientX;
        state.pointY = e.clientY;

        updateViewBox();
    });

    // Wheel event for Zooming
    svg.addEventListener('wheel', (e) => {
        e.preventDefault();

        const zoomSpeed = 0.1;
        const delta = e.deltaY > 0 ? 1 + zoomSpeed : 1 - zoomSpeed;

        // Zoom centered on mouse
        // Need to convert screen coords to SVG coords
        // Approximate for now: zoom center of viewbox

        const w = state.viewBox.w;
        const h = state.viewBox.h;

        state.viewBox.w *= delta;
        state.viewBox.h *= delta;

        // Adjust x/y to keep center stable
        state.viewBox.x += (w - state.viewBox.w) / 2;
        state.viewBox.y += (h - state.viewBox.h) / 2;

        state.scale /= delta;

        updateViewBox();
    });

    function updateViewBox() {
        svg.setAttribute('viewBox', `${state.viewBox.x} ${state.viewBox.y} ${state.viewBox.w} ${state.viewBox.h}`);
    }

    // Highlighting Logic
    // Assumes nodes have IDs and edges connect them
    // This requires structure in the SVG that we need to ensure the renderer produces
    // For now, let's just make nodes clickable to log their ID

    const nodes = document.querySelectorAll('g[id^="node-"]');
    nodes.forEach(node => {
        node.style.cursor = 'pointer';
        node.addEventListener('mouseenter', () => {
            node.style.opacity = '0.8';
        });
        node.addEventListener('mouseleave', () => {
            node.style.opacity = '1.0';
        });
        node.addEventListener('click', (e) => {
            console.log('Clicked node:', node.id);
            e.stopPropagation();
        });
    });

})();
